# Generated by cc-viewer: connect this Windows PC to __NAME__ so Claude can work on it.
# Run in PowerShell (an ordinary window is fine: it asks Windows for administrator permission by itself):
#   [Net.ServicePointManager]::SecurityProtocol='Tls12'; irm __BASE__/pc-setup/__TOK__.ps1 | iex
# The link works for 60 minutes and can be run again, also on another PC. Running it again on the same PC keeps its
# connection. Progress and errors are reported to Claude on __NAME__ by themselves.
# Everything this script installs lives in C:\ProgramData\ccviewer and the scheduled task "ccviewer-tunnel", plus the
# SSH server (Microsoft's OpenSSH package, downloaded from the server instead of Windows Update, which can hang for a long
# time) and a "cc" block at the top of ~\.ssh\config (checked before saving; the original is kept as config.before-ccviewer).
# ASCII only on purpose: Windows consoles may mangle other text. Written for Windows PowerShell 5.1.
& {
$Self = $MyInvocation.MyCommand.ScriptBlock.ToString()   # this script's own text, handed to the administrator window
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'   # Windows PowerShell's progress bar makes downloads many times slower
$Tok = '__TOK__'
$Base = '__BASE__'
$Url = "$Base/pc-setup/$Tok.ps1"
$PubGw = '__PUBGW__'
$Server = '__NAME__'            # what the server running cc-viewer is called
$RelayHost = '__RELAYHOST__'    # empty: this PC connects to the server directly
$RelayPort = '__RELAYPORT__'
$RelayUser = '__RELAYUSER__'
$TargetHost = '__TARGETHOST__'  # the server's SSH, as seen from the relay (or from here without one)
$TargetPort = '__TARGETPORT__'
$LoginUser = '__LOGINUSER__'
# no spaces in this path: ssh hands "-F <file>" on to the relay hop without quotes
$D = 'C:\ProgramData\ccviewer'
$Cfg = "$D\config"
$Task = 'ccviewer-tunnel'
$Msi = @{
    AMD64 = @('OpenSSH-Win64-v10.0.0.0.msi', 'DDEC9C53864280759CF9F74791CEFD387100E3946AA849A1C138A4ED1B96B7D9')
    ARM64 = @('OpenSSH-ARM64-v10.0.0.0.msi', '7A17D0E22D004FB47CA4BFD8FEF926FA305DE4EBF70A6F3C7A29C39AABEF0023')
}
$Utf8 = New-Object Text.UTF8Encoding $false
$Sys = New-Object Security.Principal.SecurityIdentifier 'S-1-5-18'
$Adm = New-Object Security.Principal.SecurityIdentifier 'S-1-5-32-544'
$Me = [Security.Principal.WindowsIdentity]::GetCurrent()
$S = @{ Step = 0; Ssh = $null }

function Report([string]$line) {
    # tell Claude on the server how it is going (best effort: never stops the install)
    try {
        Invoke-WebRequest -UseBasicParsing -Uri "$Base/pc-setup/$Tok.log" -Method Post -TimeoutSec 8 `
            -ContentType 'text/plain; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes($line)) | Out-Null
    } catch { }
}
function Step([int]$n, [string]$what) {
    $S.Step = $n
    Write-Host ''
    Write-Host "[$n/4] $what" -ForegroundColor Cyan
    Report "step $n/4 $what"
}
function Fail([string]$why) { throw (New-Object Exception "CCV:$why") }
function B64([string]$s) { [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($s)).TrimEnd('=').Replace('+', '-').Replace('/', '_') }
function Test-Admin { ([Security.Principal.WindowsPrincipal]$Me).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }
function Test-Port([int]$port) {
    $c = New-Object Net.Sockets.TcpClient
    try { $c.ConnectAsync('127.0.0.1', $port).Wait(2000) -and $c.Connected } catch { $false } finally { $c.Close() }
}
function Find-Ssh {
    foreach ($p in "$env:SystemRoot\System32\OpenSSH\ssh.exe", "$env:ProgramFiles\OpenSSH\ssh.exe") {
        if (Test-Path -LiteralPath $p) { return $p }
    }
    return $null
}
function Set-Access([string]$path, $owner, $sids, [switch]$Dir) {
    # only the given accounts may touch it (what OpenSSH requires of key files)
    if ($Dir) { $acl = New-Object Security.AccessControl.DirectorySecurity } else { $acl = New-Object Security.AccessControl.FileSecurity }
    $acl.SetAccessRuleProtection($true, $false)
    $acl.SetOwner($owner)
    foreach ($s in $sids) {
        if ($Dir) {
            $rule = New-Object Security.AccessControl.FileSystemAccessRule($s, 'FullControl', 'ContainerInherit,ObjectInherit', 'None', 'Allow')
        } else {
            $rule = New-Object Security.AccessControl.FileSystemAccessRule($s, 'FullControl', 'Allow')
        }
        $acl.AddAccessRule($rule)
    }
    Set-Acl -LiteralPath $path -AclObject $acl
}
function Write-Secret([string]$path, [string]$text) {
    [IO.File]::WriteAllText($path, $text.Replace("`r", '').Trim() + "`n", $Utf8)
    Set-Access $path $Me.User @($Me.User, $Sys, $Adm)
}
function Add-KeyLine([string]$path, [string]$line) {
    # rewrites the file as plain UTF-8 too: a file saved as UTF-16 (PowerShell's "echo key > file") is unreadable for sshd
    $lines = @()
    if (Test-Path -LiteralPath $path) { $lines = @(Get-Content -LiteralPath $path | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
    if ($lines -notcontains $line) { $lines += $line }
    [IO.File]::WriteAllText($path, ($lines -join "`n") + "`n", $Utf8)
}
function Run-Ssh([string]$argline, [int]$secs = 60) {
    # run ssh with a command line we write ourselves (Windows PowerShell mangles quotes in native arguments)
    # and capture its output and errors apart (2>&1 would turn ssh's messages into PowerShell errors)
    $o = Join-Path $env:TEMP ('ccviewer-' + [guid]::NewGuid().ToString('N'))
    $p = Start-Process -FilePath $S.Ssh -ArgumentList $argline -NoNewWindow -PassThru -RedirectStandardOutput "$o.out" -RedirectStandardError "$o.err"
    $null = $p.Handle   # keeps the exit code readable after the process ends
    if (-not $p.WaitForExit($secs * 1000)) { try { $p.Kill() } catch { } }
    $r = [pscustomobject]@{ Code = $p.ExitCode; Out = ''; Err = '' }
    if (Test-Path "$o.out") { $r.Out = "$(Get-Content "$o.out" -Raw)".Trim() }
    if (Test-Path "$o.err") { $r.Err = (@(Get-Content "$o.err") | Where-Object { $_.Trim() } | Select-Object -Last 3) -join ' ' }
    Remove-Item "$o.out", "$o.err" -ErrorAction SilentlyContinue
    return $r
}
function New-Key([string]$path) {
    $kg = Join-Path (Split-Path $S.Ssh) 'ssh-keygen.exe'
    $p = Start-Process -FilePath $kg -ArgumentList "-q -t ed25519 -N `"`" -C ccviewer@$env:COMPUTERNAME -f `"$path`"" -NoNewWindow -Wait -PassThru
    if (-not (Test-Path -LiteralPath $path)) { Fail "could not create a key ($path)" }
    Set-Access $path $Me.User @($Me.User, $Sys, $Adm)
}

function Main {
    Report "start windows host=$env:COMPUTERNAME user=$env:USERNAME admin=$(Test-Admin) system=$([Environment]::OSVersion.Version) arch=$env:PROCESSOR_ARCHITECTURE"
    Write-Host "Connecting this PC ($env:COMPUTERNAME, user $env:USERNAME) to $Server so Claude can work on it."
    if (-not (Test-Admin)) {
        Write-Host 'Setting up needs administrator rights. Windows will now ask for permission: click "Yes".' -ForegroundColor Yellow
        # the administrator window runs this same text (not a new download, so it works even if the link has just expired);
        # it is passed through a file in this user's TEMP folder that the new window reads and deletes right away
        $tmp = Join-Path $env:TEMP ('ccviewer-setup-' + [guid]::NewGuid().ToString('N') + '.ps1')
        [IO.File]::WriteAllText($tmp, "& {`n$Self`n}`n", $Utf8)
        $cmd = "`$f = '$tmp'; `$s = [IO.File]::ReadAllText(`$f); Remove-Item -LiteralPath `$f; Invoke-Expression `$s"
        $enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))
        try {
            Start-Process powershell.exe -Verb RunAs -ArgumentList "-NoProfile -ExecutionPolicy Bypass -NoExit -EncodedCommand $enc" | Out-Null
        } catch {
            Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue
            Fail 'administrator permission was not given (click "Yes" when Windows asks; if it asks for a password, this account may not change the PC)'
        }
        Report 'elevate: continuing in an administrator window'
        Write-Host 'Continue in the new window titled "Administrator: Windows PowerShell". This window can be closed.' -ForegroundColor Yellow
        return
    }

    Step 1 'SSH server on this PC'
    $S.Ssh = Find-Ssh
    $need = @()
    if (-not (Get-Service sshd -ErrorAction SilentlyContinue)) { $need += 'Server' }
    if (-not $S.Ssh) { $need += 'Client' }
    if ($need) {
        $arch = $env:PROCESSOR_ARCHITECTURE
        if ($env:PROCESSOR_ARCHITEW6432) { $arch = $env:PROCESSOR_ARCHITEW6432 }   # 32-bit PowerShell on 64-bit Windows
        if (-not $Msi.ContainsKey($arch)) { Fail "there is no OpenSSH package here for this processor ($arch)" }
        $name, $sha = $Msi[$arch]
        $file = Join-Path $env:TEMP $name
        Write-Host "Downloading Microsoft OpenSSH from $Server (about 6 MB)..."
        $got = $true
        try {
            Invoke-WebRequest -UseBasicParsing -Uri "$Base/pc-setup/$name" -OutFile $file -TimeoutSec 300
        } catch {
            $got = $false
            Report "note OpenSSH download from the server failed ($($_.Exception.Message)); falling back to Windows Update"
        }
        if ($got) {
            if ((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash -ne $sha) { Fail 'the downloaded SSH server package is damaged; run the command again' }
            Write-Host 'Installing it (usually under a minute)...'
            $log = Join-Path $env:TEMP 'ccviewer-openssh-install.log'
            $p = Start-Process msiexec.exe -ArgumentList "/i `"$file`" /qn /norestart ADDLOCAL=$($need -join ',') /l*v `"$log`"" -Wait -PassThru
            if ($p.ExitCode -eq 1618) { Fail 'Windows is busy installing something else (often Windows Update); wait a few minutes and run the command again' }
            if ($p.ExitCode -ne 0 -and $p.ExitCode -ne 3010) { Fail "installing the SSH server failed (msiexec exit code $($p.ExitCode); log $log)" }
            Remove-Item -LiteralPath $file -ErrorAction SilentlyContinue
        } else {
            # the server could not hand out the package: Windows' own optional feature still works, it is just slow
            Write-Host 'Could not download it from the server; installing through Windows Update instead. This can take 5 to 20 minutes: please leave this window open.' -ForegroundColor Yellow
            foreach ($f in $need) { Add-WindowsCapability -Online -Name "OpenSSH.$f~~~~0.0.1.0" | Out-Null }
        }
        $S.Ssh = Find-Ssh
        if (-not $S.Ssh -or -not (Get-Service sshd -ErrorAction SilentlyContinue)) { Fail 'OpenSSH was installed but ssh.exe or the sshd service is still missing' }
    } else {
        Write-Host 'Already installed.'
    }
    Set-Service sshd -StartupType Automatic
    Start-Service sshd
    $ok = $false
    for ($i = 0; $i -lt 10 -and -not $ok; $i++) { $ok = Test-Port 22; if (-not $ok) { Start-Sleep -Seconds 1 } }
    if (-not $ok) { Fail 'the SSH server is running but nothing answers on port 22' }
    if (-not (Test-Path HKLM:\SOFTWARE\OpenSSH)) { New-Item -Path HKLM:\SOFTWARE\OpenSSH | Out-Null }
    if (-not (Get-ItemProperty HKLM:\SOFTWARE\OpenSSH -Name DefaultShell -ErrorAction SilentlyContinue)) {
        $sh = (Get-Command pwsh -ErrorAction SilentlyContinue).Source
        if (-not $sh) { $sh = (Get-Command powershell).Source }
        New-ItemProperty -Path HKLM:\SOFTWARE\OpenSSH -Name DefaultShell -Value $sh -PropertyType String -Force | Out-Null
    }
    Write-Host 'Running.'

    Step 2 "Let Claude on $Server log in to this PC"
    # sshd reads administrators' keys from this file (only SYSTEM and Administrators may have access to it)
    New-Item -ItemType Directory -Force "$env:ProgramData\ssh" | Out-Null
    $ak = "$env:ProgramData\ssh\administrators_authorized_keys"
    Add-KeyLine $ak $PubGw
    Set-Access $ak $Adm @($Sys, $Adm)
    New-Item -ItemType Directory -Force "$env:USERPROFILE\.ssh" | Out-Null
    Add-KeyLine "$env:USERPROFILE\.ssh\authorized_keys" $PubGw
    Write-Host "Added the key of Claude on $Server (only that key; it is kept by the ssh gatekeeper on $Server for you alone)."

    Step 3 "Register this PC with $Server"
    New-Item -ItemType Directory -Force $D | Out-Null
    Set-Access $D $Adm @($Sys, $Adm, $Me.User) -Dir
    Write-Secret "$D\relay" @'
__RELAYKEY__
'@
    Write-Secret "$D\enroll" @'
__ENROLLKEY__
'@
    # host keys of the relay and the server, fixed here so ssh never has to ask
    [IO.File]::WriteAllText("$D\known_hosts", (@'
__KNOWNHOSTS__
'@).Replace("`r", '').Trim() + "`n", $Utf8)
    # this PC's tunnel key: kept across installs, so the server recognizes the PC and keeps its port
    if (-not (Test-Path "$D\tunnel")) { New-Key "$D\tunnel" }
    if (-not (Test-Path "$D\login")) { New-Key "$D\login" }
    $d = $D.Replace('\', '/')
    $relay = ''
    $jump = ''
    if ($RelayHost) {
        $relay = "Host ccviewer-relay`n    HostName $RelayHost`n    Port $RelayPort`n    User $RelayUser`n    IdentityFile $d/relay`n    IdentitiesOnly yes`n    BatchMode yes`n" +
            "    UserKnownHostsFile $d/known_hosts`n    StrictHostKeyChecking yes`n    ConnectTimeout 20`n    ServerAliveInterval 30`n    ServerAliveCountMax 3`n"
        $jump = "    ProxyJump ccviewer-relay`n"
    }
    $toServer = "    HostName $TargetHost`n    Port $TargetPort`n    User $LoginUser`n" + $jump + "    HostKeyAlias ccviewer`n" +
        "    UserKnownHostsFile $d/known_hosts`n    StrictHostKeyChecking yes`n    IdentitiesOnly yes`n"
    # used only with "ssh -F" by the tunnel, so the user's own ~/.ssh/config can never break it
    [IO.File]::WriteAllText($Cfg, "# written by the cc-viewer setup script; used only with ""ssh -F"" by the tunnel task`n" + $relay +
        "Host ccviewer-tunnel ccviewer-enroll`n" + $toServer + "    BatchMode yes`n    ConnectTimeout 20`n    ServerAliveInterval 30`n    ServerAliveCountMax 3`n" +
        "Host ccviewer-tunnel`n    IdentityFile $d/tunnel`nHost ccviewer-enroll`n    IdentityFile $d/enroll`n", $Utf8)
    $tk = (Get-Content -LiteralPath "$D\tunnel.pub" -Raw).Trim().Split(' ')
    $lk = (Get-Content -LiteralPath "$D\login.pub" -Raw).Trim().Split(' ')
    $r = Run-Ssh "-F $Cfg -n ccviewer-enroll ""enroll windows $($tk[0]) $($tk[1]) $($lk[0]) $($lk[1]) $(B64 $env:USERNAME) $(B64 $env:COMPUTERNAME)"""
    if ($r.Out -match '^ok (\d+)$') {
        $port = [int]$Matches[1]
    } elseif ($r.Out -match '^error (.*)$') {
        Fail "the server refused: $($Matches[1])"
    } else {
        Fail "could not reach the server (ssh exit code $($r.Code)): $($r.Err)"
    }
    Remove-Item -LiteralPath "$D\enroll" -ErrorAction SilentlyContinue   # the registration key is only needed once
    Write-Host "Registered: this PC's connection will be port $port on $Server."

    Step 4 'Start the connection (now and at every startup)'
    $tunnel = @'
# keeps a reverse tunnel from this PC's SSH server to the server (127.0.0.1:THEPORT); reconnects forever
$ssh = 'THESSH'
while ($true) {
    # end the previous tunnel session on the server (it may still hold the port after a drop), tell it the user name
    & $ssh -F 'THECFG' -n ccviewer-tunnel 'user64=THEUSER'
    & $ssh -F 'THECFG' -n -T -o ExitOnForwardFailure=yes -R '127.0.0.1:THEPORT:localhost:22' ccviewer-tunnel hold
    Start-Sleep -Seconds 10
}
'@
    $tunnel = $tunnel.Replace('THEPORT', "$port").Replace('THESSH', $S.Ssh).Replace('THECFG', $Cfg).Replace('THEUSER', (B64 $env:USERNAME))
    [IO.File]::WriteAllText("$D\tunnel.ps1", $tunnel, $Utf8)
    $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$D\tunnel.ps1`""
    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -ExecutionTimeLimit ([TimeSpan]::Zero) `
        -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -MultipleInstances IgnoreNew
    $who = "$env:USERDOMAIN\$env:USERNAME"
    $how = 'at every startup'
    try {
        # as this user, without a stored password, also when nobody is logged in
        $principal = New-ScheduledTaskPrincipal -UserId $who -LogonType S4U -RunLevel Highest
        Register-ScheduledTask -TaskName $Task -Action $action -Trigger (New-ScheduledTaskTrigger -AtStartup) -Principal $principal -Settings $settings -Force | Out-Null
    } catch {
        Report "note startup task refused ($($_.Exception.Message)); using a logon task instead"
        $principal = New-ScheduledTaskPrincipal -UserId $who -LogonType Interactive -RunLevel Highest
        Register-ScheduledTask -TaskName $Task -Action $action -Trigger (New-ScheduledTaskTrigger -AtLogOn -User $who) -Principal $principal -Settings $settings -Force | Out-Null
        $how = 'whenever you log in'
    }
    Stop-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue
    Start-ScheduledTask -TaskName $Task
    Write-Host 'Waiting for the connection to come up...'
    $up = $false
    for ($i = 0; $i -lt 12 -and -not $up; $i++) {
        $r = Run-Ssh "-F $Cfg -n ccviewer-tunnel status" 40
        if ($r.Out -eq 'up') { $up = $true } else { Start-Sleep -Seconds 5 }
    }
    if (-not $up) {
        $info = Get-ScheduledTaskInfo -TaskName $Task
        Fail "the connection did not come up within a minute (task result $($info.LastTaskResult); ssh said: $($r.Err))"
    }
    Write-Host "Connected (it reconnects by itself, $how)."

    # "ssh cc" on this PC goes to the server (or "ssh ccviewer" if "cc" is already taken in ~\.ssh\config).
    # Our block goes at the TOP: ssh takes the first value it finds, so a "Host *" of the user's above it would override ours;
    # it ends with "Host *" so the user's own top-level settings stay global.
    $name = $null
    try {
        $sc = "$env:USERPROFILE\.ssh\config"
        $orig = ''
        if (Test-Path -LiteralPath $sc) { $orig = [IO.File]::ReadAllText($sc) }
        # without our block from earlier runs (an older version glued its start marker onto the user's last line)
        $rest = [regex]::Replace($orig, '(?ms)^([^\r\n]*?)# >>> ccviewer[ \t]*\r?\n.*?^# <<< ccviewer[ \t]*(\r?\n|\z)',
            { param($m) if ($m.Groups[1].Value.Trim()) { $m.Groups[1].Value + "`n" } else { '' } })
        $short = 'cc'
        if ($rest -match '(?im)^\s*Host\s+(.*\s)?cc(\s|$)') { $short = 'ccviewer' }
        $block = "# >>> ccviewer`n# added by the cc-viewer setup script: ""ssh $short"" goes to $Server (the lines up to the end marker can be deleted)`n" +
            $relay + "Host $short`n" + $toServer + "    IdentityFile $d/login`nHost *`n# <<< ccviewer`n"
        [IO.File]::WriteAllText("$D\check-old", $rest, $Utf8)
        [IO.File]::WriteAllText("$D\check-new", $block + $rest, $Utf8)
        $old = Run-Ssh "-G -F $D\check-old localhost" 20
        $new = Run-Ssh "-G -F $D\check-new $short" 20
        if ($old.Code -ne 0) {
            Report "note shortcut skipped: ~/.ssh/config already broken: $($old.Err)"
            Write-Host "Note: ""ssh cc"" was not set up because ~\.ssh\config already has an error: $($old.Err)"
        } elseif ($new.Code -eq 0 -and $new.Out -match "(?m)^user $([regex]::Escape($LoginUser))\r?`$") {
            if ($orig -and -not (Test-Path -LiteralPath "$sc.before-ccviewer")) { Copy-Item -LiteralPath $sc "$sc.before-ccviewer" }
            [IO.File]::WriteAllText($sc, $block + $rest, $Utf8)
            $name = $short
        } else {
            Report "note shortcut skipped: the new ~/.ssh/config did not check out: $($new.Err)"
        }
        Remove-Item "$D\check-old", "$D\check-new" -ErrorAction SilentlyContinue
        if ($name) {
            $t = Run-Ssh "-n -o BatchMode=yes -o ConnectTimeout=20 $name exit" 40
            if ($t.Code -ne 0) { Report "note ""ssh $name"" is set up but did not log in to ${Server}: $($t.Err)" }
        }
    } catch {
        Report "note shortcut skipped: $($_.Exception.Message)"
    }

    Write-Host ''
    Write-Host "Done. Claude on $Server can now reach this PC (as $env:USERNAME)." -ForegroundColor Green
    if ($name) { Write-Host "From this PC, ""ssh $name"" takes you to $Server." }
    Report "done ok port=$port shortcut=$(if ($name) { $name } else { 'none' })"
}

try {
    Main
} catch {
    $msg = $_.Exception.Message
    if ($msg.StartsWith('CCV:')) { $msg = $msg.Substring(4) } else { $msg = "$msg (line $($_.InvocationInfo.ScriptLineNumber))" }
    Report "error step $($S.Step): $msg"
    Write-Host ''
    Write-Host "FAILED at step $($S.Step): $msg" -ForegroundColor Red
    Write-Host "Claude on $Server has been told. After fixing it you can run the same command again."
}
}
